contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    receive() external payable {}
    function test(address nonOwner, address recipient, uint256 amount) public {
        require(msg.sender == address(this));
        require(address(this).balance >= amount);
        c.fallback{value: amount}();
        bool ok;
        address prev = c.owner();
        // non-owner attempt to withdraw must fail on P
        (bool success, ) = address(c).call(
            abi.encodeWithSignature("withdrawAll(address)", recipient)
        );
        ok = success;
        assert(!ok || prev != c.owner());
    }
}

